-- SB-74: doing a chore for someone else. Siblings do each other's chores as
-- favours: if Mia takes out Leo's trash, Mia gets the points, but it's still
-- Leo's chore (his streak counts the period as done, and his rotation turn is
-- used up). See "Completions and points" in ../README.md.
--
-- The first three statements are generated by drizzle-kit (the column, its FK
-- and the "chores I did for others" index). The rest is hand-written, because
-- drizzle-kit doesn't manage functions; it replaces the 0011 functions:
--
-- - app.complete_chore_instance and app.complete_chore_stage take an optional
--   `done_by` (default NULL = the assignee did it), so existing calls keep
--   working. CREATE OR REPLACE can't add a parameter, so each is dropped and
--   created again (one function each, so no ambiguous overloads) and EXECUTE
--   is granted again as 0011 did. Both also return `credited_member_id`, who
--   got the points.
-- - app.reopen_chore_completion reverses the points of whoever the completion
--   ledger row credited (the doer), not the assignee.
-- - app.advance_chore_rotation's body moves to app.advance_chore_rotation_turn
--   (internal, not granted), so a completion that has already been authorized
--   can advance the turn when the caller can act as the doer but not as the
--   turn-holder. advance_chore_rotation keeps its checks and behaviour.
--
-- Backfill: none. NULL done_by_member_id means the assignee did it, which is
-- true of every existing row.
--
-- Custom SQLSTATEs raised here (mapped to errors in ../src/completions.ts),
-- on top of 0011's CP001-CP003:
--   CP004  `done_by` isn't a member of the chore's household

ALTER TABLE "chore_completions" ADD COLUMN "done_by_member_id" uuid;--> statement-breakpoint
ALTER TABLE "chore_completions" ADD CONSTRAINT "chore_completions_done_by_member_id_household_members_id_fk" FOREIGN KEY ("done_by_member_id") REFERENCES "public"."household_members"("id") ON DELETE set null ON UPDATE no action;--> statement-breakpoint
CREATE INDEX "chore_completions_done_by_member_id_completed_at_idx" ON "chore_completions" USING btree ("done_by_member_id","completed_at");
--> statement-breakpoint

-- The turn move itself, without the "who may do this" check: the 0009 body of
-- app.advance_chore_rotation from the stale-turn check on. Internal: called by
-- app.advance_chore_rotation (after its checks) and by
-- app.complete_chore_instance (after it has authorized the completion). Locks
-- the rotation row. Raises RT001 when the turn isn't `from_member`'s any more
-- and RT002 when nobody is eligible.
CREATE OR REPLACE FUNCTION app.advance_chore_rotation_turn(
	chore uuid,
	from_member uuid,
	completed boolean
) RETURNS TABLE (member_id uuid, wrapped boolean)
	LANGUAGE plpgsql VOLATILE SECURITY DEFINER
	SET search_path = pg_catalog, public
	AS $$
	#variable_conflict use_column
	DECLARE
		r public.chore_rotations%ROWTYPE;
		cur_position smallint;
		next_member uuid;
		next_wrapped boolean;
	BEGIN
		SELECT * INTO r FROM public.chore_rotations c
		WHERE c.chore_id = chore
		FOR UPDATE;
		IF NOT FOUND THEN
			RAISE EXCEPTION 'no rotation for chore %', chore
				USING ERRCODE = 'no_data_found';
		END IF;

		IF r.current_member_id IS DISTINCT FROM from_member THEN
			RAISE EXCEPTION 'the turn has already moved on (it is now %)', r.current_member_id
				USING ERRCODE = 'RT001';
		END IF;

		SELECT m.position INTO cur_position
		FROM public.chore_rotation_members m
		WHERE m.chore_id = chore AND m.member_id = r.current_member_id;

		SELECT n.member_id, n.wrapped INTO next_member, next_wrapped
		FROM app.next_rotation_member(chore, cur_position, NULL) n;
		IF next_member IS NULL THEN
			RAISE EXCEPTION 'rotation for chore % has no eligible members', chore
				USING ERRCODE = 'RT002';
		END IF;

		UPDATE public.chore_rotations c
		SET current_member_id = next_member,
			turn_started_at = now(),
			last_completed_member_id = CASE WHEN completed THEN r.current_member_id ELSE c.last_completed_member_id END,
			last_completed_at = CASE WHEN completed THEN now() ELSE c.last_completed_at END,
			updated_at = now()
		WHERE c.chore_id = chore;

		RETURN QUERY SELECT next_member, next_wrapped;
	END
	$$;
--> statement-breakpoint

-- Same signature, checks and behaviour as 0009; the turn move is now
-- app.advance_chore_rotation_turn.
CREATE OR REPLACE FUNCTION app.advance_chore_rotation(
	chore uuid,
	from_member uuid,
	completed boolean
) RETURNS TABLE (member_id uuid, wrapped boolean)
	LANGUAGE plpgsql VOLATILE SECURITY DEFINER
	SET search_path = pg_catalog, public
	AS $$
	#variable_conflict use_column
	DECLARE
		r public.chore_rotations%ROWTYPE;
	BEGIN
		SELECT * INTO r FROM public.chore_rotations c
		WHERE c.chore_id = chore
		FOR UPDATE;
		IF NOT FOUND OR NOT app.is_household_member(r.household_id) THEN
			RAISE EXCEPTION 'no rotation for chore %', chore
				USING ERRCODE = 'no_data_found';
		END IF;

		IF completed THEN
			IF NOT (
				app.is_household_parent(r.household_id)
				OR (r.current_member_id IS NOT NULL AND app.can_act_as_member(r.current_member_id))
			) THEN
				RAISE EXCEPTION 'only a parent or the member whose turn it is can complete this turn'
					USING ERRCODE = 'insufficient_privilege';
			END IF;
		ELSIF NOT app.is_household_parent(r.household_id) THEN
			RAISE EXCEPTION 'only a parent can skip a turn'
				USING ERRCODE = 'insufficient_privilege';
		END IF;

		RETURN QUERY
		SELECT a.member_id, a.wrapped
		FROM app.advance_chore_rotation_turn(chore, from_member, completed) a;
	END
	$$;
--> statement-breakpoint

-- Who did a chore instance, after checking the signed-in user may say so.
-- Internal: called by the completion functions below with the locked
-- instance's household and assignee. Returns the doer: `done_by`, or the
-- assignee when `done_by` is NULL.
--
-- - The assignee did it (`done_by` NULL or the assignee): a parent, or someone
--   who can act as the assignee (themselves, or a managed kid they parent).
--   This is the 0011 rule.
-- - Someone else did it: `done_by` must be in the same household (CP004), and
--   the user must be a parent (who can record any member as the doer, e.g. a
--   managed kid did a sibling's chore) or able to act as `done_by` (saying
--   they did it themselves). Being the assignee isn't enough to name someone
--   else, so a kid can't hand their points to a sibling.
CREATE OR REPLACE FUNCTION app.authorize_chore_doer(
	household uuid,
	assignee uuid,
	done_by uuid
) RETURNS uuid
	LANGUAGE plpgsql STABLE SECURITY DEFINER
	SET search_path = pg_catalog, public
	AS $$
	BEGIN
		IF done_by IS NULL OR done_by = assignee THEN
			IF NOT (app.is_household_parent(household) OR app.can_act_as_member(assignee)) THEN
				RAISE EXCEPTION 'only a parent or the assignee can complete this chore'
					USING ERRCODE = 'insufficient_privilege';
			END IF;
			RETURN assignee;
		END IF;

		IF NOT app.is_member_id_in(household, done_by) THEN
			RAISE EXCEPTION 'member % is not in this household', done_by
				USING ERRCODE = 'CP004';
		END IF;
		IF NOT (app.is_household_parent(household) OR app.can_act_as_member(done_by)) THEN
			RAISE EXCEPTION 'only a parent or the member who did it can record who did this chore'
				USING ERRCODE = 'insufficient_privilege';
		END IF;
		RETURN done_by;
	END
	$$;
--> statement-breakpoint

